def cc(g,diag):
 R,C=len(g),len(g[0]); seen=set(); out=[]
 for r in range(R):
  for c in range(C):
   if g[r][c]==0 and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c)); z=[]
    while q:
     x,y=q.pop();z.append((x,y))
     for dx in (-1,0,1):
      for dy in (-1,0,1):
       if not (dx or dy) or (not diag and dx and dy):continue
       a,b=x+dx,y+dy
       if 0<=a<R and 0<=b<C and g[a][b]==0 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
    out.append((len(z),z))
 return out
